-- BSD recipes (Bill of Materials) from COGS_BSD.xlsx, linked to the menu imported
-- in 39_import_menu_bsd.sql. Only outlet BSD gets recipes. Existing stock items are
-- reused by name; missing ones are created. Skipped: lines marked "GAK USAH / JANGAN
-- MASUK BOM", Oreo (Cookies n Cream), and the MILKY BERRY sheet (not on the menu).
-- Generated by a one-off script; edit recipes in the app afterwards, not here.
START TRANSACTION;
SET @bsd := (SELECT id FROM outlets WHERE code = 'BSD');

-- Stock items (created only when missing).
INSERT INTO stock_items (sku, name, unit_id, category_id, account_id, reorder_level, status)
SELECT 'TMP-NEW', 'BEANS HB', (SELECT id FROM units WHERE code = 'GR'), (SELECT id FROM stock_item_categories WHERE name = 'Raw Material'), (SELECT id FROM accounts WHERE code = '5000.041'), 0, 'ACTIVE'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM stock_items WHERE name = 'BEANS HB');
UPDATE stock_items SET sku = CONCAT('ITM-', LPAD(id, 5, '0')) WHERE sku = 'TMP-NEW';
