-- Recipes (73 products, outlet BSD).

-- BEV-00002
INSERT INTO recipes (outlet_id, product_id, version_no, yield_qty, is_active)
SELECT @bsd, id, 1, 1, 1 FROM products WHERE sku = 'BEV-00002';
INSERT INTO recipe_items (recipe_id, stock_item_id, qty, unit_id)
SELECT r.id, si.id, l.qty, un.id FROM recipes r JOIN products p ON p.id = r.product_id AND p.sku = 'BEV-00002'
JOIN (SELECT 'BEANS HB' AS n, 18 AS qty, 'GR' AS u UNION ALL SELECT 'AIR MINERAL' AS n, 150 AS qty, 'ML' AS u UNION ALL SELECT 'SEDOTAN' AS n, 1 AS qty, 'PACK' AS u UNION ALL SELECT 'CUP PLASTIK' AS n, 1 AS qty, 'PCS' AS u) l JOIN stock_items si ON si.name = l.n JOIN units un ON un.code = l.u
WHERE r.outlet_id = @bsd;

